import{_ as t,o as a,c as r,X as o}from"./chunks/framework.pSp8ynCZ.js";const u=JSON.parse('{"title":"CellPack","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/docs/index.md","filePath":"overview.md"}'),c={name:"rust/docs/index.md"};function d(s,e,l,n,i,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="cellpack" tabindex="-1">CellPack <a class="header-anchor" href="#cellpack" aria-label="Permalink to &quot;CellPack&quot;">​</a></h1><p>CellPack is a Rust library for matrix storage and bounded data loading. It compresses each row into an independently decodable record, packs records onto pages, and delivers requested rows through a fixed-capacity output ring. It is designed for single-cell training pipelines that need random row access, explicit column mapping, multiple outputs, and planned reuse of input data.</p><p>This manual covers the Rust crate <code>cellpack</code>. The Python distribution and import package are named <code>pycellpack</code> and have separate documentation. The examples here use the Rust core directly and require neither Python bindings nor a GPU.</p><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><ul><li>New to CellPack? Follow <a href="/cellpack-docs/rust/docs/installation.html">installation</a> and the <a href="/cellpack-docs/rust/docs/quickstart.html">quickstart</a>.</li><li>Building a pipeline? Read <a href="/cellpack-docs/rust/docs/data-sources.html">data sources</a>, <a href="/cellpack-docs/rust/docs/accesses.html">access sequences</a>, and <a href="/cellpack-docs/rust/docs/loading.html">loading</a>.</li><li>Managing cache and memory? Start with <a href="/cellpack-docs/rust/docs/planning.html">planning</a>, <a href="/cellpack-docs/rust/docs/performance.html">performance</a>, and <a href="/cellpack-docs/rust/docs/profiling.html">profiling</a>.</li><li>Integrating lower-level components? See <a href="/cellpack-docs/rust/docs/codecs.html">codecs</a>, <a href="/cellpack-docs/rust/docs/process-functions.html">process functions</a>, the <a href="/cellpack-docs/rust/docs/format.html">file format</a>, and <a href="/cellpack-docs/rust/docs/architecture.html">architecture</a>.</li><li>Exploring the public surface? The <a href="/cellpack-docs/rust/api/">API reference</a> groups interfaces by module, with parameter/return types and <a href="/cellpack-docs/rust/api/contracts.html">data contracts</a>.</li></ul><h2 id="what-the-library-provides" tabindex="-1">What the library provides <a class="header-anchor" href="#what-the-library-provides" aria-label="Permalink to &quot;What the library provides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Entry point</th></tr></thead><tbody><tr><td>Stream CSR or dense rows into a <code>.cpk</code> file</td><td><code>store::CpkWriter</code></td></tr><tr><td>Read ranges, gathers, and repeated rows into owned buffers</td><td><code>store::CpkFile</code>, <code>ReadSelection</code></td></tr><tr><td>Encode and decode chunks or records in caller buffers</td><td><code>scans</code></td></tr><tr><td>Combine matrices with an explicit shared column vocabulary</td><td><code>loader::DataSourceBuilder</code></td></tr><tr><td>Produce multiple fixed-size outputs per sequence position</td><td><code>loader::Loader</code>, <code>OutputSchema</code></td></tr><tr><td>Plan reuse of compressed pages and decoded input rows</td><td><code>opt</code></td></tr><tr><td>Inspect event counters and selected timing sites</td><td><code>loader::RunStats</code>, <code>prof</code></td></tr></tbody></table><p>A <code>.cpk</code> stream contains a matrix, without row labels, column labels, or annotations. The application owns names, vocabulary construction, sampling, training, and device transfers. Compression preserves value bit patterns; requesting a different output dtype introduces that conversion&#39;s precision limits.</p>',8)])])}const m=t(c,[["render",d]]);export{u as __pageData,m as default};
